 panel_reset();g.x=panel_cx(0)-3.5f;g.z=PANEL_Z-5.8f;g.playerY=3;liftY[0]=liftTarget[0]=3;flatOpen=9;entryOpen=2;save_game();panel_reset();g.playerY=0;CHECK(load_game()&&g.playerY==3&&liftY[0]==3&&flatOpen==9&&entryOpen==2,"v10 saves preserve floor, apartment doors and lift positions");
